mapper.update:
UPDATE t_screening_hit h JOIN t_screening_run r ON r.screening_run_id = h.screening_run_id
SET h.status = 'SUPERSEDED', h.version = h.version + 1, h.update_time = #{now}
WHERE r.case_subject_id = #{caseSubjectId} AND r.program_screening_id = #{programScreeningId}
AND r.screening_run_id <> #{keepRunId} AND h.status IN ('OPEN', 'RESOLVED')
